// Isolation test (OS-12) — construct Ratio with its declared inputs and nothing else, then exercise every
// public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { height } from "../src/kernel/index.js";
import { Ratio, type CandidateCounts } from "../src/spend/index.js";
import { c0, c1, u } from "./support/spend-parts.js";

const counts = (a: number, b: number): CandidateCounts => ({ countsAsOf: () => [{ currency: c0, count: a }, { currency: c1, count: b }] });
const at = height(1);

describe("Ratio in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new Ratio({} as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    expect(() => new Ratio({ candidates: {} as never })).toThrow();
  });

  it("of answers differently when candidates differs", () => {
    expect(new Ratio({ candidates: counts(1, 4) }).of(u).compute(at)).not.toEqual(new Ratio({ candidates: counts(4, 16) }).of(u).compute(at));
  });
});
